use std :: time :: Duration ; use schemars :: JsonSchema ; use serde :: { Deserialize , Serialize } ; use crate :: { ModelId , ProviderId } ; impl ModelTestResult { # [doc = " Creates a successful test result."] pub fn success (provider_id : ProviderId , model_id : ModelId , time_to_first_token : Duration , total_duration : Duration ,) -> Self { let ttft_secs = time_to_first_token . as_secs_f64 () ; let speed_score = if ttft_secs <= 1.0 { 1.0 } else if ttft_secs <= 3.0 { 0.8 } else if ttft_secs <= 5.0 { 0.6 } else if ttft_secs <= 10.0 { 0.4 } else { 0.2 } ; Self { provider_id , model_id , success : true , time_to_first_token : Some (time_to_first_token) , total_duration : Some (total_duration) , score : speed_score , error : None , } } # [doc = " Creates a failed test result."] pub fn failure (provider_id : ProviderId , model_id : ModelId , error : String ,) -> Self { Self { provider_id , model_id , success : false , time_to_first_token : None , total_duration : None , score : 0.0 , error : Some (error) , } } }